<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">__HAL_RCC_AFIO_CLK_ENABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
